(function(){
 'use strict';
 window.WBDailyUI=function(ctx,helpers){const {M,esc:e,icon,heading,modal,toast}=ctx;let period='daily';
  const config={daily:{name:'每日记录',intro:'用几句话，为明天留一个清楚的起点。',fields:['今天推进了什么？','遇到了什么问题？','下一步做什么？']},weekly:{name:'每周复盘',intro:'结合本周真实完成与发布记录，决定继续或调整。',fields:['本周完成了什么？证据在哪里？','哪些值得继续，哪些应该停止？','下周最重要的一步是什么？']},monthly:{name:'每月复盘',intro:'回看方向、投入和真正留下来的积累。',fields:['目标与业务有了什么进展？','积累了哪些作品、知识与能力？','下个月准备调整什么？']}};
  function today(){const state=ctx.getState(),items=state.tasks.filter(t=>t.date===M.todayKey()),overdue=M.carryOver(state),done=items.filter(t=>t.doneAt!==null).length,total=items.reduce((n,t)=>n+t.minutes,0);return `<section class="panel daily-panel" data-home-block="today">${heading('今天',`${M.todayKey()} · 已完成 ${done} / ${items.length} 项 · 计划 ${total} 分钟`,`<button class="small-button" data-action="new-task">${icon('plus')}添加任务</button>`)}${overdue.length?`<div class="overdue-tasks"><h3>昨天没做完的 ${overdue.length} 件</h3>${overdue.map(t=>`<div class="overdue-row"><span><strong>${e(t.title)}</strong><small>${e(t.date)}</small></span><div><button class="small-button" data-action="carry-task" data-id="${e(t.id)}">带入今天</button><button class="text-button" data-action="delete-task" data-id="${e(t.id)}">不做了</button></div></div>`).join('')}</div>`:''}${total>60?'<p class="daily-soft-warning">超过今天约 1 小时的计划</p>':''}${items.length?`<div class="tasks">${ctx.tasksHTML()}</div>`:'<p class="empty-inline">今天还没有安排。先选一个能留下结果的小行动。</p>'}</section>`;}
  function home(data){const state=ctx.getState(),published=M.publishedThisWeek(state),next=[...state.topics].filter(t=>t.status!=='沉淀').sort((a,b)=>(a.status==='制作中'?0:1)-(b.status==='制作中'?0:1))[0],active=data.projects.filter(p=>p.next&&!/暂停|已归档|已结束|不再推进/.test(p.status||'')),preferred=['social-content','personal-workbench','packrivo'].map(id=>active.find(p=>p.id===id)).filter(Boolean),projects=[...preferred,...active.filter(p=>!preferred.includes(p))].slice(0,3);return `${!data.connected?'<p class="home-disconnected" role="status">本机资料尚未连接或正在整理。今日记录可在连接完成后保存，项目和资讯会自动重试加载。</p>':''}<div class="home-v04">${today()}<section class="panel" data-home-block="week">${heading('本周内容','同一张卡跨平台发布，只计一条。',`<a class="text-button" href="#content">查看选题卡 ${icon('arrow-right')}</a>`)}<div class="home-week-summary"><div class="weekly-published-count">本周已发 ${published.length} 条 <small>/ 目标 3 条</small></div><div class="weekly-next">${next?`<strong>下一张卡停在：${e(M.topicStep(next))}</strong><button class="text-button" data-action="topic-edit" data-id="${e(next.id)}">${e(next.title)} ${icon('arrow-right')}</button>`:'从一个真实问题开始，先做一张选题卡。'}</div></div></section><div class="home-v04-bottom"><section class="panel" data-home-block="projects">${heading('进行中的项目','先推进一个能留下结果的小步骤。',`<a class="text-button" href="#projects">全部项目 ${icon('arrow-right')}</a>`)}${projects.length?projects.map(p=>`<div class="home-project-next"><div><strong>${e(p.title)}</strong><p>${e(p.next)}</p></div><button class="small-button" data-action="project-task" data-id="${e(p.id)}">把下一步加入今天</button></div>`).join(''):'<p class="empty-inline">资料连接后显示项目。</p>'}</section><section class="panel home-one" data-home-block="one">${heading('今日一条','一条值得看，一件值得试。',`<a class="text-button" href="#radar">更多资讯 ${icon('arrow-right')}</a>`)}${data.news?data.newsCard(data.news,true):'<p class="empty-inline">还没有公开资讯缓存，可到资讯页手动刷新。</p>'}${data.tool?data.toolHTML(data.tool):''}</section></div></div>`;}
  function facts(){const state=ctx.getState(),tasks=state.tasks.filter(t=>t.doneAt!==null&&!t.legacyDoneTime&&M.weekKey(t.doneAt)===M.weekKey()),topics=M.publishedThisWeek(state);return `<section class="review-week-facts"><h3>本周留下的事实</h3><strong>已完成任务</strong>${tasks.length?`<ul>${tasks.map(t=>`<li>${e(t.title)}</li>`).join('')}</ul>`:'<p>本周还没有可确认完成时间的任务记录。</p>'}<strong>本周已发选题</strong>${topics.length?`<ul>${topics.map(t=>`<li>${e(t.title)}</li>`).join('')}</ul>`:'<p>本周还没有带发布日期的已发选题。</p>'}</section>`;}
  function review(){const c=config[period],key=M.periodKey(period),values=ctx.getState().reviews[period][key]||[],history=M.reviewEntries(ctx.getState(),period);return `<div class="tab-bar" aria-label="复盘周期">${Object.entries(config).map(([id,c])=>`<button data-action="daily-period" data-value="${id}" aria-pressed="${id===period}" class="${id===period?'active':''}">${c.name}</button>`).join('')}</div><div class="review-layout"><section class="panel"><div class="review-heading">${icon('notebook-pen')}<div><h2>${c.name} · ${e(key)}</h2><p>${c.intro}</p></div></div>${period==='weekly'?facts():''}<form id="review-form" data-period="${period}" data-key="${e(key)}">${c.fields.map((label,i)=>`<label class="review-field">${label}<textarea name="review-${i}" rows="3" maxlength="5000">${e(values[i]||'')}</textarea></label>`).join('')}<div class="form-footer"><span>输入停顿800毫秒后保存到本机，浏览器留副本。</span><button class="primary-button" type="submit">保存${c.name}</button></div></form>${period==='daily'?`<button class="outline-button review-next-task" data-action="review-tomorrow" data-key="${e(key)}">${icon('plus')}把下一步加入明天</button>`:''}<section class="review-history"><h3>最近 7 次记录</h3>${history.length?history.map(r=>`<button class="review-history-row" data-action="review-history" data-period="${period}" data-key="${e(r.key)}"><strong>${e(r.key)}</strong><span>${e((r.values[0]||'空记录').slice(0,70))}</span>${icon('chevron-right')}</button>`).join(''):'<p class="small-caption">保存后会出现在这里，每个日期或周期单独保留。</p>'}</section></section><aside class="review-aside"><h2>少记一点，留清下一步</h2><p>复盘不是再建一份待办；确认要做的事，再加入具体日期。</p><ul><li>留下作品或完成证据</li><li>区分事实、推测与感受</li><li>决定继续、停止或调整</li></ul></aside></div>`;}
  function capture(form){const f=new FormData(form);M.saveReview(ctx.getState(),form.dataset.period,form.dataset.key,[0,1,2].map(i=>String(f.get('review-'+i)||'')));}
  function trial(task){const saved=ctx.getState().trialResults[task.sourceId]||{};modal('记录这次工具试用',`<p class="dialog-lead">${e(task.title)}</p><form id="trial-result-form" data-tool="${e(task.sourceId)}"><label class="form-field">试了什么？<textarea name="what" required rows="3" maxlength="5000">${e(saved.what||'')}</textarea></label><label class="form-field">结果如何？<textarea name="result" required rows="3" maxlength="5000">${e(saved.result||'')}</textarea></label><label class="form-field">能不能讲给同行？<select name="canTeach" required><option value="">请选择</option><option ${saved.canTeach===true?'selected':''}>能</option><option ${saved.canTeach===false?'selected':''}>不能</option></select></label><div class="dialog-actions"><button type="button" class="outline-button" data-action="close">稍后再写</button><button class="primary-button" type="submit">保存试用结果</button></div></form>`,'试用到内容');}
  function toggle(id){const task=ctx.getState().tasks.find(t=>t.id===id);if(!task)return false;const done=M.toggleTask(ctx.getState(),id);ctx.save();ctx.render();if(done&&task.sourceType==='trial')trial(task);else document.querySelector('#done-'+id)?.focus();return true;}
  function handle(action,el){const state=ctx.getState(),id=el.dataset.id;if(action==='carry-task'){M.bringToToday(state,id);ctx.save();ctx.render();toast('已带入今天');return true;}if(action==='delete-task'){M.deleteTask(state,id);ctx.save();ctx.render();toast('已移除这件事');return true;}if(action==='daily-period'){period=el.dataset.value;ctx.render();return true;}if(action==='review-tomorrow'){const form=document.querySelector('#review-form');if(form)capture(form);const task=M.reviewNextTask(state,el.dataset.key);if(!task){toast('先写下“下一步做什么”');return true;}ctx.save();toast('已加入 '+task.date+' 的任务');return true;}if(action==='review-history'){const values=state.reviews[el.dataset.period]?.[el.dataset.key];if(values)modal(config[el.dataset.period].name+' · '+el.dataset.key,`<p class="quiet-note">历史记录，只读回看。</p>${config[el.dataset.period].fields.map((label,i)=>`<div class="detail-block"><h3>${label}</h3><p class="pre-wrap">${e(values[i]||'未填写')}</p></div>`).join('')}`,'历史复盘');return true;}if(action==='trial-record'){const task=state.tasks.find(t=>t.id===id);if(task)trial(task);return true;}return false;}
  function submit(form){if(form.id==='review-form'){capture(form);ctx.save();ctx.render();toast(config[form.dataset.period].name+'已保存');return true;}if(form.id==='trial-result-form'){const f=new FormData(form),id=form.dataset.tool,answer=M.saveTrialResult(ctx.getState(),id,{what:String(f.get('what')),result:String(f.get('result')),canTeach:f.get('canTeach')==='能'});ctx.save();document.querySelector('#dialog').close();ctx.render();if(answer.canTeach){const tool=ctx.D.tools.find(t=>t.id===id);helpers.openTopic({title:(tool?.name||id)+'试用：一个可复现的小案例',source:{type:'trial',id,label:tool?.name||id},steps:answer.what,result:answer.result,check:'请补充让同行照做和检查的条件'});}else toast('已保存试用结果');return true;}return false;}
  function input(target){const form=target.closest('#review-form');if(!form)return false;if(!ctx.isReady()){toast('本机记录正在连接，请稍候');return true;}capture(form);ctx.save(true);return true;}
  return {today,home,review,handle,submit,input,toggle};
 };
})();
